function openTab(e,t){var n,s,o=document.getElementsByClassName("tabcontent");for(n=0;n<o.length;n++)o[n].style.display="none";s=document.getElementsByClassName("tablinks");for(n=0;n<s.length;n++)s[n].className=s[n].className.replace(" active","");document.getElementById(t).style.display="block",e.currentTarget.className+=" active",shadeActiveTab()}function shadeActiveTab(){var e,t,n=document.getElementsByClassName("tablinks");for(e=0;e<n.length;e++)n[e].classList.remove("tab-active-bg");t=document.querySelector(".tablinks.active"),t&&t.classList.add("tab-active-bg")}document.addEventListener("DOMContentLoaded",function(){shadeActiveTab()})